-- Report:  RPT_100_Deals not applied due to Cost override on PO
-- Module:  Other
-- Source:  RPT_100_Deals not applied due to Cost override on PO.dva
-- Generated by MFCS DVA SQL Extractor


-- ── Query 1 ────────────────────────────────────────────────────────────
SELECT     TRUNC(SYSDATE)                                        AS REPORT_DATE,     oh.ORDER_NO                                           AS PO_NUMBER,     oh.STATUS                                             AS PO_STATUS,     oh.WRITTEN_DATE                                       AS WRITTEN_DATE,     oh.SUPPLIER                                           AS SUPPLIER_ID,     sp.SUP_NAME                                           AS SUPPLIER_NAME,     ol.ITEM                                               AS ITEM_ID,     im.ITEM_DESC                                          AS ITEM_DESCRIPTION,     ol.LOCATION                                           AS LOCATION_ID,     ol.LOC_TYPE                                           AS LOC_TYPE,     ol.UNIT_COST                                          AS PO_UNIT_COST,     iscl.UNIT_COST                                        AS EXPECTED_COST,     CASE         WHEN iscl.UNIT_COST IS NULL          THEN 'NO EXPECTED COST ON FILE'         WHEN ol.UNIT_COST &lt;&gt; iscl.UNIT_COST  THEN 'Y'         ELSE 'N'     END                                                   AS COST_OVERRIDE_IND,     dh.DEAL_ID                                            AS ELIGIBLE_DEAL_ID,     dil.DEAL_DETAIL_ID                                    AS DEAL_COMPONENT_ID,     dh.BILLING_TYPE                                       AS DEAL_BILLING_TYPE,     CASE WHEN odd.DISCOUNT_AMT_PER_UNIT IS NULL THEN 'NOT APPLIED' ELSE 'APPLIED' END                                                           AS DEAL_APPLICATION_STATUS,     CASE         WHEN iscl.UNIT_COST IS NULL THEN             'No standard cost on file for comparison'         WHEN ol.UNIT_COST &lt;&gt; iscl.UNIT_COST THEN             'PO cost was changed from the standard cost, so the deal discount could not be applied'         ELSE             'Deal not applied for a reason other than cost'     END                                                   AS REASON  FROM  MFCS_RDS.RDS_WV_ORDHEAD                 oh JOIN  MFCS_RDS.RDS_WV_ORDLOC                  ol   ON oh.ORDER_NO = ol.ORDER_NO JOIN  MFCS_RDS.RDS_WV_ITEM_MASTER             im   ON ol.ITEM     = im.ITEM JOIN  MFCS_RDS.RDS_WV_DEAL_ITEMLOC_ITEM       dil  ON ol.ITEM     = dil.ITEM AND ol.LOCATION = dil.LOCATION JOIN  MFCS_RDS.RDS_WV_DEAL_DETAIL             dd   ON dil.DEAL_ID = dd.DEAL_ID AND dil.DEAL_DETAIL_ID = dd.DEAL_DETAIL_ID JOIN  MFCS_RDS.RDS_WV_DEAL_HEAD               dh   ON dd.DEAL_ID  = dh.DEAL_ID AND dh.STATUS = 'A' LEFT JOIN MFCS_RDS.RDS_WV_ITEM_SUPP_COUNTRY_LOC iscl        ON ol.ITEM = iscl.ITEM AND ol.LOCATION = iscl.LOC AND oh.SUPPLIER = iscl.SUPPLIER LEFT JOIN MFCS_RDS.RDS_WV_SUPS                sp   ON oh.SUPPLIER = sp.SUPPLIER LEFT JOIN MFCS_RDS.RDS_WV_ORDLOC_DISCOUNT     odd  ON ol.ORDER_NO = odd.ORDER_NO AND ol.ITEM = odd.ITEM                                         AND ol.LOCATION = odd.LOCATION AND dh.DEAL_ID = odd.DEAL_ID  WHERE     oh.STATUS IN ('W','S','A')     AND ol.UNIT_COST &lt;&gt; iscl.UNIT_COST     AND odd.DISCOUNT_AMT_PER_UNIT IS NULL  ORDER BY oh.WRITTEN_DATE DESC, oh.ORDER_NO, ol.ITEM</ds:dbquery><ds:target_type>Oracle 12c</ds:target_type><ds:object_name/></ds:dataptr><ds:columns><ds:column><ds:name>REPORT_DATE</ds:name><ds:datatype>timestamp</ds:datatype></ds:column><ds:column><ds:name>PO_NUMBER</ds:name><ds:datatype>number</ds:datatype><ds:nullable>false</ds:nullable></ds:column><ds:column><ds:name>PO_STATUS</ds:name><ds:datatype>varchar(1)</ds:datatype><ds:nullable>false</ds:nullable></ds:column><ds:column><ds:name>WRITTEN_DATE</ds:name><ds:datatype>timestamp</ds:datatype><ds:nullable>false</ds:nullable></ds:column><ds:column><ds:name>SUPPLIER_ID</ds:name><ds:datatype>number</ds:datatype><ds:nullable>false</ds:nullable></ds:column><ds:column><ds:name>SUPPLIER_NAME</ds:name><ds:datatype>varchar(240)</ds:datatype></ds:column><ds:column><ds:name>ITEM_ID</ds:name><ds:datatype>varchar(25)</ds:datatype><ds:nullable>false</ds:nullable></ds:column><ds:column><ds:name>ITEM_DESCRIPTION<