EAL_APPLICATION_STATUS_0bfd3a26-72a4-41bb-9e68-957dc70ff8e7\",\"originalColumnName\":\"DEAL_APPLICATION_STATUS\",\"isUserCalculation\":true,\"isApplied\":false,\"transformEngine\":\"bis\"},\"sourceexpr\":\"\\\"DEAL_APPLICATION_STATUS_0bfd3a26-72a4-41bb-9e68-957dc70ff8e7\\\"\",\"errorStatus\":\"\"}],\"options\":{\"outputColumnDataType\":\"varchar(11)\",\"outputColumnAggrRule\":\"none\",\"outputColumnHidden\":false,\"outputColumnDisplayName\":\"Deal Application Status\",\"isEditorValid\":true,\"afterColumn\":\"DEAL_APPLICATION_STATUS\"},\"applied\":true,\"inplace\":true,\"rename\":true,\"allowEdit\":true,\"generatesOutputColumns\":true,\"unsavedTransform\":false,\"parentId\":\"19\"},{\"id\":\"23\",\"type\":\"RENAME_COLUMN\",\"sourceColumns\":[\"DEAL_BILLING_TYPE\"],\"expressionSourceColumns\":[\"DEAL_BILLING_TYPE\"],\"outputColumns\":[{\"name\":\"DEAL_BILLING_TYPE_e39c2b0d-8187-47d0-88a7-aa6499d2cccf\",\"displayName\":\"Deal Billing Type\",\"exclude\":false,\"datatype\":\"varchar(6)\",\"aggrRule\":\"none\",\"uiOptions\":{\"prepColumnName\":\"DEAL_BILLING_TYPE_e39c2b0d-8187-47d0-88a7-aa6499d2cccf\",\"originalColumnName\":\"DEAL_BILLING_TYPE\",\"isUserCalculation\":true,\"isApplied\":false,\"transformEngine\":\"bis\"},\"sourceexpr\":\"\\\"DEAL_BILLING_TYPE_e39c2b0d-8187-47d0-88a7-aa6499d2cccf\\\"\",\"errorStatus\":\"\"}],\"options\":{\"outputColumnDataType\":\"varchar(6)\",\"outputColumnAggrRule\":\"none\",\"outputColumnHidden\":false,\"outputColumnDisplayName\":\"Deal Billing Type\",\"isEditorValid\":false,\"afterColumn\":\"DEAL_BILLING_TYPE\"},\"applied\":true,\"inplace\":true,\"rename\":true,\"allowEdit\":true,\"generatesOutputColumns\":true,\"unsavedTransform\":false,\"parentId\":\"22\"},{\"id\":\"24\",\"type\":\"RENAME_COLUMN\",\"sourceColumns\":[\"DEAL_COMPONENT_ID\"],\"expressionSourceColumns\":[\"DEAL_COMPONENT_ID\"],\"outputColumns\":[{\"name\":\"DEAL_COMPONENT_ID_0ce4e547-315e-4ff8-ad41-90c769a9fb95\",\"displayName\":\"Deal Component ID\",\"exclude\":false,\"datatype\":\"number\",\"aggrRule\":\"sum\",\"uiOptions\":{\"prepColumnName\":\"DEAL_COMPONENT_ID_0ce4e547-315e-4ff8-ad41-90c769a9fb95\",\"originalColumnName\":\"DEAL_COMPONENT_ID\",\"isUserCalculation\":true,\"isApplied\":false,\"transformEngine\":\"bis\"},\"sourceexpr\":\"\\\"DEAL_COMPONENT_ID_0ce4e547-315e-4ff8-ad41-90c769a9fb95\\\"\",\"errorStatus\":\"\"}],\"options\":{\"outputColumnDataType\":\"number\",\"outputColumnAggrRule\":\"sum\",\"outputColumnHidden\":false,\"outputColumnDisplayName\":\"Deal Component ID\",\"isEditorValid\":false,\"afterColumn\":\"DEAL_COMPONENT_ID\"},\"applied\":true,\"inplace\":true,\"rename\":true,\"allowEdit\":true,\"generatesOutputColumns\":true,\"unsavedTransform\":false,\"parentId\":\"23\"},{\"id\":\"25\",\"type\":\"PROPERTY_CHANGE\",\"sourceColumns\":[\"DEAL_COMPONENT_ID_0ce4e547-315e-4ff8-ad41-90c769a9fb95\"],\"expressionSourceColumns\":[\"DEAL_COMPONENT_ID_0ce4e547-315e-4ff8-ad41-90c769a9fb95\"],\"outputColumns\":[],\"options\":{\"outputColumnAggrRule\":\"none\",\"outputColumnDisplayName\":\"Deal Component ID\",\"outputColumnRole\":\"Attribute\",\"afterColumn\":\"DEAL_COMPONENT_ID_0ce4e547-315e-4ff8-ad41-90c769a9fb95\"},\"applied\":true,\"inplace\":true,\"rename\":false,\"allowEdit\":false,\"generatesOutputColumns\":false,\"unsavedTransform\":false,\"parentId\":\"24\"}],\"recommendations\":[],\"dataSubsetInfos\":{\"queryEditMode\":1,\"filterbarSettings\":{},\"uiSqlStatement\":\"

-- ── Query 2 ────────────────────────────────────────────────────────────
SELECT\\n    TRUNC(SYSDATE)                                        AS REPORT_DATE,\\n    oh.ORDER_NO                                           AS PO_NUMBER,\\n    oh.STATUS                                             AS PO_STATUS,\\n    oh.WRITTEN_DATE                                       AS WRITTEN_DATE,\\n    oh.SUPPLIER                                           AS SUPPLIER_ID,\\n    sp.SUP_NAME                                           AS SUPPLIER_NAME,\\n    ol.ITEM                                               AS ITEM_ID,\\n    im.ITEM_DESC                                          AS ITEM_DESCRIPTION,\\n    ol.LOCATION                                           AS LOCATION_ID,\\n    ol.LOC_TYPE                                           AS LOC_TYPE,\\n    ol.UNIT_COST                                          AS PO_UNIT_COST,\\n    iscl.UNIT_COST                                        AS EXPECTED_COST,\\n    CASE\\n        WHEN iscl.UNIT_COST IS NULL          THEN 'NO EXPECTED COST ON FILE'\\n        WHEN ol.UNIT_COST &lt;&gt; iscl.UNIT_COST  THEN 'Y'\\n        ELSE 'N'\\n    END                                                   AS COST_OVERRIDE_IND,\\n    dh.DEAL_ID                                            AS ELIGIBLE_DEAL_ID,\\n    dil.DEAL_DETAIL_ID                                    AS DEAL_COMPONENT_ID,\\n    dh.BILLING_TYPE                                       AS DEAL_BILLING_TYPE,\\n    CASE WHEN odd.DISCOUNT_AMT_PER_UNIT IS NULL THEN 'NOT APPLIED' ELSE 'APPLIED' END\\n                                                          AS DEAL_APPLICATION_STATUS,\\n    CASE\\n        WHEN iscl.UNIT_COST IS NULL THEN\\n            'No standard cost on file for comparison'\\n        WHEN ol.UNIT_COST &lt;&gt; iscl.UNIT_COST THEN\\n            'PO cost was changed from the standard cost, so the deal discount could not be applied'\\n        ELSE\\n            'Deal not applied for a reason other than cost'\\n    END                                                   AS REASON\\n\\nFROM  MFCS_RDS.RDS_WV_ORDHEAD                 oh\\nJOIN  MFCS_RDS.RDS_WV_ORDLOC                  ol   ON oh.ORDER_NO = ol.ORDER_NO\\nJOIN  MFCS_RDS.RDS_WV_ITEM_MASTER             im   ON ol.ITEM     = im.ITEM\\nJOIN  MFCS_RDS.RDS_WV_DEAL_ITEMLOC_ITEM       dil  ON ol.ITEM     = dil.ITEM AND ol.LOCATION = dil.LOCATION\\nJOIN  MFCS_RDS.RDS_WV_DEAL_DETAIL             dd   ON dil.DEAL_ID = dd.DEAL_ID AND dil.DEAL_DETAIL_ID = dd.DEAL_DETAIL_ID\\nJOIN  MFCS_RDS.RDS_WV_DEAL_HEAD               dh   ON dd.DEAL_ID  = dh.DEAL_ID AND dh.STATUS = 'A'\\nLEFT JOIN MFCS_RDS.RDS_WV_ITEM_SUPP_COUNTRY_LOC iscl\\n       ON ol.ITEM = iscl.ITEM AND ol.LOCATION = iscl.LOC AND oh.SUPPLIER = iscl.SUPPLIER\\nLEFT JOIN MFCS_RDS.RDS_WV_SUPS                sp   ON oh.SUPPLIER = sp.SUPPLIER\\nLEFT JOIN MFCS_RDS.RDS_WV_ORDLOC_DISCOUNT     odd  ON ol.ORDER_NO = odd.ORDER_NO AND ol.ITEM = odd.ITEM\\n                                        AND ol.LOCATION = odd.LOCATION AND dh.DEAL_ID = odd.DEAL_ID\\n\\nWHERE\\n    oh.STATUS IN ('W','S','A')\\n    AND ol.UNIT_COST &lt;&gt; iscl.UNIT_COST\\n    AND odd.DISCOUNT_AMT_PER_UNIT IS NULL\\n\\nORDER BY oh.WRITTEN_DATE DESC, oh.ORDER_NO, ol.ITEM;\"},\"editorCurrentState\":false,\"joins\":{\"tables\":[]}}</ds:uiOptions><ds:version>v5</ds:version></ds:datasetImportOptions>","business-model":"\"\"","active":true,"custom-attrs":"{\"src_parquet_verified\":\"true\"}","description":"External dataset","display-name":"Manual Query","locale":"sys","is-user-striped":false,"file-length":0,"type":"sql","properties-last-modified":"2026-07-30T12:00:54.573+0000","connection-namespace":"disadmin_disadmin_APPID","private-connection":false,"credential-exists":true,"connection-name":"Remote RDS MFCS Connection","provider-type":"db","provider-name":"oracle","sso-enabled":false,"datamodelname":"'OracleRetailCloudAdmin@deloitte.com'.'RPT_100_Deals_Not_applied_Cost_Override Dataset'","parent-namespace":"OracleRetailCloudAdmin@deloitte.com","parent-name":"RPT_100_Deals_Not_applied_Cost_Override Dataset","data-access-mode":"auto","is-data-cacheable":true,"checkpoint-metadata-stale":false,"owner-guid":"OracleRetailCloudAdmin@deloitte.com","is-temporary":false},"datasetType":"EMBEDDED","datamodelTwoPartName":"'OracleRetailCloudAdmin@deloitte.com'.'RPT_100_Deals_Not_applied_Cost_Override Dataset'"}
